// scene_art.h -- THE SCENE ADJUSTMENTS' NEW ART (a mod: settings.h sceneAdjust, with the widescreen; outside the ROM mandate,
// docs/WIDESCREEN.md "Scene adjustments"). A scene the original draws for 256 columns only gets art of its own past that edge,
// drawn after the scene's design in its own resolution and palettes: cells that name the scene's own tiles (as a BG map
// does: tile, palette, priority, flips -- the tiles themselves come from the player's VRAM, none of the ROM's pixels is here)
// and pixels of new art over them (CGRAM indices). Generated by tools/scene_art_entry3.py into src/art/.
#ifndef CT_SCENE_ART_H
#define CT_SCENE_ART_H

#include "seq_pic.h"

// Sequence entry 3 (`FF 23` after the Blackbird, `FF 63` in the attract): the machine rising over the planet. Its BG1 is the
// field's machinery laid out as one screen (BG1SC 00), symmetric about the field's column 128 and shown 8 pixels to the right
// (the setup's VRAM read gives the first word twice, seq_entry3pic.c): the art is its left side, the right one its mirror.
// A CtSeqPicArtFn (seq_pic.h g_seqPicArt).
int CtSceneArtEntry3(const CtSeqPic* p, int layer, int* mx, int my, int pri);
// What it draws, set at the stage's start: steam -- the Steam release's own art for the scene first (the Steam margins, a
// mod: the player's ct_wide.dat, its location 06B); own -- the scene adjustments' own art (a mod). The sky's and the planet's
// rules (one moon, the planet mirrored past the 256) hold with either.
void CtSceneArtEntry3Set(int steam, int own);

#endif
